from pathlib import Path
root=Path(__file__).resolve().parents[1]
path=root/'app.js'
s=path.read_text(encoding='utf-8')
start=s.index('function home(){')
end=s.index('\nfunction ',start+1)
new=r'''function homeCard(p){return `<article class="product-card"><div class="product-photo"><a href="/products/${p.id}">${img(p.image,name(p))}</a></div><h3><a href="/products/${p.id}">${name(p)}</a></h3><p>${text(p,'description')||text(p,'line')}</p><div class="product-meta">${link('/products/'+p.id,'تفاصيل القطعة','DISCOVER')}<span>${t('السعر عند الطلب','PRICE ON REQUEST')}</span></div></article>`}
function home(){return `<div class="reference-home">
<section class="hero"><img class="hero-media" src="/assets/hero.webp" alt="${t('سجاد حرير ومقتنيات إرث','Silk and keepsakes by IRTH')}" fetchpriority="high"><video class="hero-media" id="hero-video" autoplay muted loop playsinline preload="metadata" poster="/assets/hero.webp" aria-label="${t('فيلم إرث — ملمس الحرير','IRTH film — the touch of silk')}"><source src="/assets/hero.mp4" type="video/mp4"></video><div class="hero-shade"></div><div class="hero-copy"><h1>${t('فن الاقتناء من بيت إرث','THE ART OF COLLECTING')}<span class="latin-title">IRTH HOUSE</span></h1><p>${t('حرير تنسجه الأيدي، ومقتنيات تحمل حكاية.<br>قطع نختارها لجمال صنعتها وعمق معناها، لترافقك اليوم وتبقى لمن بعدك.','Handwoven silk and objects with a story.<br>Chosen for the beauty of their craft and the meaning they carry. Made to be treasured, today and tomorrow.')}</p>${link('/catalog','اكتشف المجموعة','EXPLORE THE COLLECTION')}</div><button class="video-control" data-action="video" aria-label="${t('إيقاف الفيديو','Pause film')}">${icon('pause')}</button></section>
<section class="philosophy" id="philosophy">${ornament()}<h2>${t('فلسفة بيت إرث','THE PHILOSOPHY OF')}<span dir="ltr">IRTH HOUSE</span></h2><p>${t('إرث هو ما نحمله من حكايات، وما نختار أن نتركه من جمال. من عقدة حرير تصوغها يد صبور، إلى مقتنى يحتفظ بذاكرة المكان، نجمع قطعًا تُرى فيها عناية الصانع وتُلمس فيها قيمة المعنى. أشياء تُقتنى لتُورث.','Heritage lives in the stories we carry and the beauty we leave behind. From a silk knot shaped by a patient hand to an object that holds the memory of a place, our collection celebrates the maker’s care. Objects to treasure, and to pass on.')}</p></section>
<section class="craft-story"><figure class="craft-banner">${img('craft',t('يد تنسج خيوط الحرير على النول','Silk threads knotted by hand on a loom'))}<a href="/journal/the-language-of-silk" class="craft-inset">${img('silk-detail',t('تفاصيل النسيج الحريري','A close view of the silk weave'))}<span>${t('حكاية كل عقدة','A story in every knot')}</span></a><svg class="craft-pointer" viewBox="0 0 100 130" aria-hidden="true"><path d="M1 1 97 125"/><circle cx="97" cy="125" r="2"/></svg></figure></section>
<section class="collections-home"><div class="collections-content"><h2>${t('مقتنيات لكل حكاية<br>ولكل مناسبة','A COLLECTION FOR<br>EVERY OCCASION')}</h2><div class="collection-portrait">${img('carpet',t('سجادة حريرية من مجموعة إرث','A silk rug from the IRTH collection'))}</div><ol class="collection-list">${['silk','beads','kiswah','rihal'].map((id,i)=>`<li><a href="/collections/${id}"><small dir="ltr">/0${i+1}</small><span>${name(collections[id])}</span></a></li>`).join('')}</ol></div><span class="signature">by IRTH HOUSE</span></section>
<section class="new-editorial">${img('silk-editorial',t('الحرير في بيت إرث','Silk in the house of IRTH'),'backdrop')}<h2 class="editorial-heading">${t('إصدارات جديدة<br>وقطع مختارة','NEW ARRIVALS<br>& HOUSE FAVOURITES')}</h2><div class="film-strip"><span class="signature">New 2026</span><p class="edition-description">${t('اكتشف الفصل الجديد من بيت إرث.<br><br>سجاد من الحرير، ومسابح تحتفظ بملمس الحجر، ومقتنيات تستحضر ذاكرة المكان. اختيارات للبيت وللإهداء، تجمعها عناية واحدة بالتفاصيل.','Discover a new chapter of IRTH HOUSE.<br><br>Silk rugs, the natural texture of stone prayer beads, and keepsakes that recall a place. Pieces for the home and thoughtful gifts, united by care for every detail.')}</p>${['beads','pendant','silk-detail'].map((key,i)=>`<a href="/products/${[products[1].id,products[2].id,products[0].id][i]}">${img(key,t('من المجموعة الجديدة','From the new collection'))}</a>`).join('')}</div>${link('/catalog','تصفح الكتالوج','VIEW THE CATALOGUE','button light edition-cta')}</section>
<section class="products-section home-products"><div class="container"><div class="section-head"><h2>${t('مختارات من<br>بيت إرث','OUR MOST<br>LOVED PIECES')}</h2></div><div class="product-grid">${[products[0],products[2],products.find(p=>p.id==='rihal-kaaba-door')].map(homeCard).join('')}</div>${link('/catalog','جميع القطع','ALL PIECES','rule-link all-pieces')}</div></section>
<section class="collector"><div class="collector-intro"><h2>${t('عن قرب…<br>حكايات المقتنيات','A CLOSER LOOK<br>AT THE COLLECTION')}</h2><p>${t('من ملمس الحرير إلى تفاصيل الإهداء.<br>لحظات نقترب فيها من القطع، لنرى ما يمنح كل واحدة منها حكايتها.','From the texture of silk to the details of a gift.<br>A closer look at the things that give each piece its story.')}</p></div><div class="gallery-stage" id="gallery-stage">${gallery()}</div></section>
<section class="faq" id="faq"><h2>FAQ</h2>${faqList()}</section>
<section class="home-inquiry">${img('silk-editorial',t('تفاصيل من بيت إرث','A detail from the house of IRTH'),'inquiry-backdrop')}<div class="inquiry-panel">${ornament()}<h2>${t('هل لديك استفسار؟','HOW CAN WE HELP?')}</h2><p>${t('اترك لنا تفاصيل اختيارك،<br>لنبدأ معًا حكاية القطعة.','Tell us what you have in mind.<br>Every selection begins with a conversation.')}</p>${contactForm('contact')}</div></section>
</div>`}
'''
s=s[:start]+new+s[end:]
# Compact mobile language switch stays available within the navigation panel.
s=s.replace('<nav class="menu-links"><button class="mobile-search-link"','<nav class="menu-links"><button class="menu-language" data-action="language">${t(\'English\',\'العربية\')}</button><button class="mobile-search-link"')
path.write_text(s,encoding='utf-8')
p=root/'index.html';html=p.read_text(encoding='utf-8')
html=html.replace('<link rel="stylesheet" href="/refinement.css">','<link rel="stylesheet" href="/refinement.css">\n  <link rel="stylesheet" href="/assets/reference-fonts.css">\n  <link rel="stylesheet" href="/reference-match.css?v=20260915">')
html=html.replace('/app.js?v=20260914','/app.js?v=20260915')
p.write_text(html,encoding='utf-8')
print('Homepage aligned to reference composition; internal catalogue retained.')
